questions.starter:
def group(n):
    """Return the group of component n ("01" to "11", or 1 to 11) on the map:
    "core", "feeds", "governs" or "scale". Anything else raises ValueError."""
    k = int(n)
    if k == 1:
        return "core"
    if 2 <= k <= 5:
        return "feeds"
    if 6 <= k <= 8:
        return "governs"
    return "scale"

questions.solution:
GROUPS = {1: "core", 2: "feeds", 3: "feeds", 4: "feeds", 5: "feeds",
          6: "governs", 7: "governs", 8: "governs", 11: "governs",
          9: "scale", 10: "scale"}


def group(n):
    """Return the group of component n ("01" to "11", or 1 to 11) on the map:
    "core", "feeds", "governs" or "scale". Anything else raises ValueError."""
    if isinstance(n, str) and len(n) == 2 and n.isdigit():
        k = int(n)
    elif isinstance(n, int) and not isinstance(n, bool):
        k = n
    else:
        raise ValueError(f"not a component number: {n!r}")
    if k not in GROUPS:
        raise ValueError(f"not a component number: {n!r}")
    return GROUPS[k]

questions.tests:
expected = {"01": "core", "02": "feeds", "03": "feeds", "04": "feeds", "05": "feeds",
            "06": "governs", "07": "governs", "08": "governs",
            "09": "scale", "10": "scale", "11": "governs"}
for n, g in expected.items():
    assert group(n) == g, (n, group(n), g)
    assert group(int(n)) == g, (int(n), g)

# observability is numbered last but governs the loop; it is not part of the scale tier
assert group("11") == "governs"
assert group(9) == "scale" and group(10) == "scale"

# anything that is not a component number, or not written as one, is refused
for bad in (0, 12, "00", "12", -1, "011", 1.5):
    try:
        group(bad)
    except ValueError:
        pass
    else:
        raise AssertionError(f"group({bad!r}) should raise ValueError")
print("all tests passed")
